# 数据文件：source/src/utils/plugins/installedPluginsManager.ts
# slug = src_utils_plugins_installedPluginsManager_ts
# 约束：中文用三引号；正文禁英文双引号与反斜杠。

ANNOTATIONS = [
    (1, 'after', '''本模块是整个插件系统的「安装状态账本」。核心设计：安装状态是全局的（插件要么在磁盘上、要么不在），而启用禁用状态是「按仓库」的，留在各仓库的 settings.json 里。所以这里只管「装了没有、装在哪、哪个版本」，不管「当前仓库开没开」。'''),
    (37, 'after', '''类型别名：V2 把每个插件映射到「一组安装项」数组，而不是单个安装项。这样同一个插件可以在 user、project、local 等多个作用域各装一份。'''),
    (58, 'after', '''迁移开关用模块级变量记录。目的是防止同一个会话里重复跑迁移（迁移涉及改名与删文件，重复跑会出错或浪费 IO）。'''),
    (66, 'after', '''V2 格式的带记忆化缓存。一次 CLI 会话内反复读 installed_plugins.json 很常见，缓存避免重复读盘；文件被改动时由 clearInstalledPluginsCache 清掉强制重载。'''),
    (73, 'after', '''启动时的「内存快照」。这是正在运行的会话实际使用的状态，后台更新只改磁盘文件、不碰这份内存——这样后台悄悄下载新版本时，当前会话继续用旧版本，刷新时才切换。'''),
    (78, 'after', '''拿到 installed_plugins.json 的绝对路径，统一从这里读写，避免路径散落各处。'''),
    (99, 'after', '''清空缓存。注意它连 inMemoryInstalledPlugins 一起清，因为文件被改后内存快照也失效了。绝大多数情况只在初始化或测试时调用；后台更新请用 updateInstallationPathOnDisk，它只清磁盘缓存、保留内存快照。'''),
    (105, 'after', '''migrateToSinglePluginFile 把旧的 V1/V2 双文件方案合并成单文件。三种情况：有 v2 文件就改名成主文件；只有 version=1 的主文件就原地转 V2；都没有就当无需迁移。每次会话启动只跑一次。'''),
    (124, 'after', '''情况一：直接尝试把 v2 文件改名成主文件；抛 ENOENT 说明 v2 文件不存在，落到下面的分支。改名成功顺手清理遗留的非版本化缓存目录。'''),
    (140, 'after', '''情况二：v2 不在。尝试读主文件；再抛 ENOENT 说明两个文件都没有（情况三），直接标记迁移完成返回，无文件可迁。'''),
    (154, 'after', '''情况四里的子分支：主文件是 version=1，用 schema 校验后调用 migrateV1ToV2 原地转成 V2 写回。这里同样清理遗留缓存目录。'''),
    (184, 'after', '''cleanupLegacyCache 清理「非版本化的旧缓存目录」。旧结构是 cache 下直接平铺插件名，新结构是 cache 下按 市场/插件/版本 三级。只删那些「不在任何安装记录里引用」的遗留目录，避免误删还在用的版本化目录。'''),
    (215, 'after', '''判断一个顶层目录是「版本化结构」（市场目录，下面有 插件/版本）还是「遗留平铺结构」。版本化的要跳过，只清理遗留的平铺目录。'''),
    (254, 'after', '''readInstalledPluginsFileRaw 读原始文件：文件不存在返回 null（不报错），文件在但解析不了才抛错。返回时顺便推断 version（缺省按 1 处理）。'''),
    (280, 'after', '''migrateV1ToV2 把 V1 数据转 V2。关键决策：V1 没有作用域概念，所以所有旧安装统一归到 user 作用域，并且用 市场/插件/版本 的版本化缓存路径重算 installPath，而不是沿用 V1 的旧路径。'''),
    (307, 'after', '''loadInstalledPluginsV2 是读主入口，带缓存。优先返回缓存；读到的数据按 version 走 V2 校验或 V1 转换；文件不存在或解析失败都降级返回空 V2 对象，不让上层崩。'''),
    (366, 'after', '''saveInstalledPluginsV2 写主入口，是 V1/V2 合并后的唯一真相源。写完同步更新内存缓存，保证下次读一致。'''),
    (406, 'after', '''addPluginInstallation 在指定作用域新增或更新一条安装项。同一插件下按「作用域 + 项目路径」找已有项，有就覆盖、没有就追加；新增项带上安装时间，更新项刷新 lastUpdated。'''),
    (445, 'after', '''removePluginInstallation 按「作用域 + 项目路径」删一条安装项；某个插件的所有安装项都删光后，把整个插件键也删掉。'''),
    (488, 'after', '''getInMemoryInstalledPlugins 取会话内存快照（懒加载）：首次调用才从磁盘加载并缓存，之后整个会话都复用这份，不会被后台更新影响。'''),
    (502, 'after', '''loadInstalledPluginsFromDisk 绕过所有缓存、直接从磁盘读。专供后台更新器用，这样它检查变更时不会污染运行中会话的内存视图。'''),
    (537, 'after', '''updateInstallationPathOnDisk 是后台更新器的核心：只在磁盘上更新某插件的安装路径和版本，绝不改内存快照。这样后台下完新版本写盘，当前会话继续用旧版本，直到用户主动刷新才切。写完后清磁盘缓存但不动内存缓存。'''),
    (589, 'after', '''hasPendingUpdates 判断「磁盘与内存是否不一致」——即后台更新器是否已经下载了新版本但会话还没切换。逐条比对同作用域同项目的 installPath 是否不同。'''),
    (656, 'after', '''getPendingUpdatesDetails 给出待更新列表的明细（插件 id、作用域、旧版本、新版本），供界面展示「有 N 个更新可用」。'''),
    (702, 'after', '''resetInMemoryState 只在启动或测试时调用，把内存快照置空以便重新加载。'''),
    (714, 'after', '''initializeVersionedPlugins 是初始化总入口，三步：先合并单文件迁移，再同步 settings.json 的启用插件，最后加载内存快照。REPL 和无头模式都要尽早调用。'''),
    (746, 'after', '''removeAllPluginsForMarketplace 一键移除某市场下的全部插件：按 @市场名 后缀匹配，收集它们的安装路径（留给孤儿清理）后整批删除、写盘一次。返回被删路径和插件 id 供上层继续清理磁盘。'''),
    (784, 'after', '''isInstallationRelevantToCurrentProject 是整份文件最重要的语义判断之一。installed_plugins.json 是「用户级单文件、记了所有作用域」，所以「插件装了没」几乎总被理解为「装在当前项目可用」，而不是「装在这台机器任何地方」。user/managed 作用域全局相关；project/local 只有项目路径匹配当前项目才算。特别用 getOriginalCwd 而不是 getCwd——「当前项目」指 Claude Code 启动时的目录，不是工作目录漂移到的地方。注释还复盘了 #29608：DiscoverPlugins 曾把只装在别的项目里的插件也隐藏了。'''),
    (800, 'after', '''函数签名：入参是一条安装项，返回它是否与当前项目相关（user/managed 恒真，project/local 需项目路径匹配）。'''),
    (818, 'after', '''isPluginInstalled 判断插件是否「以与当前项目相关的方式」装了。除了作用域匹配，还要过一道 settings.enabledPlugins 守卫：若启用列表与安装文件因 settings.json 被覆盖而分歧，返回假，让用户能重新启用。'''),
    (833, 'after', '''isPluginGloballyInstalled 只在「存在 user 或 managed 作用域安装」时为真。它决定界面要不要提供「安装」入口——全局装了就没啥可加的。注释复盘了 gh-29997 / gh-29240 / gh-29392：浏览界面曾被 isPluginInstalled 卡住（它对项目级安装也返回真），导致用户无法给同一插件再加一个 user 级条目；后端早就支持每插件多作用域，只是前端的门判断错了。'''),
    (849, 'after', '''函数签名：判断插件是否有全局（user/managed）安装项，同样带 settings 分歧守卫。'''),
    (874, 'after', '''addInstalledPlugin 新增或更新插件安装元数据，默认作用域 user（向后兼容）。它保留该插件在其他作用域的已有安装项，只在目标作用域新增或覆盖一条。注意它只写注册表文件，真正删物理文件要另行调用 deletePluginCache。'''),
    (914, 'after', '''removeInstalledPlugin 从注册表删除插件，返回被删的元数据（从第一条安装项提取 V1 兼容字段）供上层使用。注意它只更新注册表，删磁盘物理文件要再调 deletePluginCache。'''),
    (954, 'after', '''deletePluginCache 真正从磁盘物理删除插件缓存目录（递归强制删）。删完还会顺手清理空的父目录（cache/市场/插件），避免留下空壳目录。'''),
    (965, 'after', '''函数签名：入参是插件缓存目录的绝对路径，物理删除它。'''),
    (1002, 'after', '''getGitCommitSha 从某 git 仓库目录取当前 HEAD 的 commit sha，不是 git 仓库或失败则返回 undefined——用于给 git 类插件记录版本指纹。'''),
    (1010, 'after', '''getPluginVersionFromManifest 直接读插件清单 plugin.json 拿版本号，读不到返回 unknown。'''),
    (1027, 'after', '''migrateFromEnabledPlugins 把 settings.json 的 enabledPlugins 同步进 installed_plugins.json。采用「基于版本号」的策略：文件不存在、schema 过旧、或有新插件出现时才更新，方便以后加字段只需升版本号加迁移逻辑。对 settings 里启用了但 installed 里没有的插件，去市场查真实安装路径、抽清单版本、抓 git sha。'''),
    (1063, 'after', '''性能优化：若主文件已是 V2 且 settings 里的插件全已存在，就跳过昂贵的「查市场 / 抓 git sha」步骤直接返回，避免每次启动都做大量 IO。'''),
    (1106, 'after', '''按来源遍历 settings：顺序很重要，user 在前、project 次之、local 最后——最具体的作用域「后写覆盖」，最终 local 优先于 project 优先于 user。settings.json 是作用域的真相源。'''),
    (1202, 'after', '''读缓存目录时，readdir 本身就是第一个真正动作，不是「先检查再读」的预检。它的 ENOENT 直接告诉我们缓存不存在，下游操作也能优雅处理 ENOENT——这不是 TOCTOU 竞态，因为即使目录在 readdir 和后续读之间被删，也只是降级成版本 unknown，不会崩溃。'''),
]
